INSERT INTO "Car" ("id", "createdAt", "brand", "model", "description", "rating", "type", "capacity", "steering", "gasoline", "price", "discount", "images") VALUES ('82', '2025-01-14 04:27:52', 'Toyota', 'Xtra', 'Torquatis.'' Numquam hoc ita defendit Epicurus neque Metrodorus aut quisquam eorum, qui aut saperet aliquid aut ista didicisset. Et quod quaeritur saepe, cur tam multos legant, quam legendi sunt. Quid enim me prohiberet Epicureum esse, si probarem, quae ille diceret? Cum praesertim illa perdiscere ludus esset. Quam ob rem voluptas expetenda, fugiendus dolor sit. Sentiri haec.', '4.1870', 'Sedan', '3', 'Auto', '68', '112.75', '25', '{"https://sampledomain.com/car13.jpg","https://sampledomain.com/car14.jpg"}');
INSERT INTO "Car" ("id", "createdAt", "brand", "model", "description", "rating", "type", "capacity", "steering", "gasoline", "price", "discount", "images") VALUES ('83', '2024-04-13 23:32:18', 'Mitsubishi', 'Pajero', 'Umquam cohaerescent, sive aliae declinabunt, aliae suo nutu recte ferentur, primum erit hoc quasi, provincias atomis dare, quae recte, quae oblique ferantur, deinde eadem illa constituto veri a falso distinctio traditur. Restat locus huic disputationi vel maxime necessarius de amicitia, quam, si voluptas summum sit bonum, affirmatis nullam omnino fore. De qua.', '3.6196', 'Hatchback', '5', 'Manual', '39', '131.81', '2', '{"https://sampledomain.com/car75.jpg","https://sampledomain.com/car76.jpg"}');
INSERT INTO "Car" ("id", "createdAt", "brand", "model", "description", "rating", "type", "capacity", "steering", "gasoline", "price", "discount", "images") VALUES ('84', '2025-01-11 05:26:26', 'Mercury', 'Milan', 'Sit nisi cum voluptate vivere. Huic certae stabilique sententiae quae sint coniuncta explicabo brevi. Nullus in ipsis error est finibus bonorum et malorum, id est voluptatem et dolorem? Sunt autem quidam e nostris, qui haec subtilius velint tradere et.', '0.3849', 'Convertible', '5', 'Auto', '61', '358.81', '43', '{"https://sampledomain.com/car9.jpg","https://sampledomain.com/car10.jpg"}');
INSERT INTO "Car" ("id", "createdAt", "brand", "model", "description", "rating", "type", "capacity", "steering", "gasoline", "price", "discount", "images") VALUES ('85', '2024-02-02 02:07:00', 'Mazda', 'MX-5', 'Dolor afferat, eorum tamen utrumque et ortum esse e corpore et ad usus civium non inutile, nosque ea scripta reliquaque eiusdem generis et legimus libenter et legemus --, haec, quae vitam omnem continent, neglegentur? Nam, ut sint opera, studio, labore meo doctiores cives mei, nec cum iracundia aut pertinacia recte disputari potest. Sed ad haec, nisi.', '0.6728', 'Coupe', '7', 'Manual', '58', '132.68', '2', '{"https://sampledomain.com/car75.jpg","https://sampledomain.com/car76.jpg"}');
INSERT INTO "Car" ("id", "createdAt", "brand", "model", "description", "rating", "type", "capacity", "steering", "gasoline", "price", "discount", "images") VALUES ('86', '2024-10-16 10:30:48', 'Chrysler', 'Imperial', 'Ipsum, quosque labores propter suam voluptatem susciperet, eosdem suscipiet propter amici voluptatem. Quaeque de virtutibus dicta sunt, explicabo. Nemo enim ipsam voluptatem, quia voluptas sit, aspernatur aut odit.', '1.5314', 'SUV', '1', 'Auto', '99', '105.47', '48', '{"https://sampledomain.com/car15.jpg","https://sampledomain.com/car16.jpg"}');
INSERT INTO "Car" ("id", "createdAt", "brand", "model", "description", "rating", "type", "capacity", "steering", "gasoline", "price", "discount", "images") VALUES ('87', '2024-03-21 18:28:09', 'Kia', 'Rio', 'Non intellegentium nihil dolendum esse animo, quod sit a dolore corporis praesenti futurove seiunctum. Nec vero hoc oratione solum, sed multo etiam magis, quod.', '2.9770', 'MUV', '3', 'Auto', '96', '125.39', '15', '{"https://sampledomain.com/car83.jpg","https://sampledomain.com/car84.jpg"}');
INSERT INTO "Car" ("id", "createdAt", "brand", "model", "description", "rating", "type", "capacity", "steering", "gasoline", "price", "discount", "images") VALUES ('88', '2024-09-28 05:46:41', 'Buick', 'Lucerne', 'Numquid tibi videtur de voluptatibus suis cogitavisse? Sed ut omittam pericula, labores, dolorem etiam, quem optimus quisque pro patria et pro suis suscipit, ut non plus voluptatum habeat.', '0.2423', 'Coupe', '2', 'Manual', '15', '215.71', '39', '{"https://sampledomain.com/car55.jpg","https://sampledomain.com/car56.jpg"}');
