INSERT INTO "Notification" ("id", "createdAt", "text", "isSeen", "userId") VALUES ('1', '2024-10-05 17:29:17', 'Putant. Quae autem inanes sunt.', '0', '2');
INSERT INTO "Notification" ("id", "createdAt", "text", "isSeen", "userId") VALUES ('2', '2024-10-16 14:46:12', 'Vivere cum dolore, cui sententiae consentaneum est ultimum esse bonorum eum voluptate vivere. Huic certae stabilique sententiae quae.', '1', '8');
INSERT INTO "Notification" ("id", "createdAt", "text", "isSeen", "userId") VALUES ('3', '2024-08-12 15:14:14', 'Inimicus paene nomini Romano est.', '1', '1');
INSERT INTO "Notification" ("id", "createdAt", "text", "isSeen", "userId") VALUES ('4', '2024-06-06 20:23:41', 'Esse non possunt, conficiuntur et angore et metu maximeque cruciantur, cum sero sentiunt frustra se aut pecuniae studuisse aut imperiis aut opibus aut gloriae. Nullas enim.', '1', '7');
INSERT INTO "Notification" ("id", "createdAt", "text", "isSeen", "userId") VALUES ('5', '2024-05-28 03:30:38', 'Consectetur adipiscing elit, sed do eiusmod tempor incididunt ut labore et dolore magnam aliquam quaerat voluptatem. Ut enim mortis metu omnis quietae vitae status perturbatur, et ut succumbere doloribus eosque.', '0', '7');
INSERT INTO "Notification" ("id", "createdAt", "text", "isSeen", "userId") VALUES ('6', '2024-04-09 11:23:54', 'Ostendis. Sed uti oratione perpetua malo quam interrogare aut interrogari. Ut placet, inquam. Tum dicere exorsus est. Primum igitur, inquit.', '0', '4');
INSERT INTO "Notification" ("id", "createdAt", "text", "isSeen", "userId") VALUES ('7', '2024-04-04 06:06:18', 'Esse et voluptates et dolores animi quam corporis. Nam corpore nihil nisi praesens et quod adest sentire possumus, animo autem et praeterita et futura. Ut enim aeque doleamus.', '1', '7');
INSERT INTO "Notification" ("id", "createdAt", "text", "isSeen", "userId") VALUES ('8', '2024-03-22 22:45:02', 'Quo offendimur, dolor, doloris omnis privatio recte nominata est voluptas. Ut enim, cum cibo et potione fames sitisque depulsa est.', '1', '4');
INSERT INTO "Notification" ("id", "createdAt", "text", "isSeen", "userId") VALUES ('9', '2024-05-17 23:54:55', 'Honestatis decore laudandis, id totum.', '0', '5');
INSERT INTO "Notification" ("id", "createdAt", "text", "isSeen", "userId") VALUES ('10', '2024-05-04 03:44:03', 'Inquit, totum Epicurum paene e philosophorum choro sustulisti. Quid ei reliquisti, nisi te, quoquo modo loqueretur, intellegere, quid.', '0', '1');
INSERT INTO "Notification" ("id", "createdAt", "text", "isSeen", "userId") VALUES ('11', '2024-08-08 01:42:34', 'Opera multa nec impensa expleantur; ne naturales quidem multa desiderant, propterea quod ipsa natura, ut ait ille, sciscat et probet, id est quo melius viveremus, eas ergo artes persequeretur, vivendi artem tantam tamque et operosam et perinde fructuosam relinqueret? Non ergo Epicurus ineruditus, sed ii indocti, qui, quae.', '0', '9');
INSERT INTO "Notification" ("id", "createdAt", "text", "isSeen", "userId") VALUES ('12', '2024-11-07 10:45:54', 'Accedit etiam mors, quae quasi saxum Tantalo semper impendet.', '0', '1');
INSERT INTO "Notification" ("id", "createdAt", "text", "isSeen", "userId") VALUES ('13', '2024-05-11 18:23:45', 'Defatigatio turpis est, cum id, quod ipsi statuerunt, non possunt, victi et debilitati obiecta.', '0', '3');
INSERT INTO "Notification" ("id", "createdAt", "text", "isSeen", "userId") VALUES ('14', '2024-03-25 06:46:34', 'Perspiciatis, unde omnis iste natus error sit voluptatem accusantium doloremque.', '1', '5');
INSERT INTO "Notification" ("id", "createdAt", "text", "isSeen", "userId") VALUES ('15', '2024-07-09 07:54:58', 'Voluptatis affert? Nec mihi illud dixeris: ''Haec enim ipsa mihi sunt voluptati, et erant illa Torquatis.'' Numquam hoc ita defendit Epicurus neque Metrodorus aut quisquam eorum, qui aut saperet aliquid aut ista didicisset. Et quod quaeritur saepe, cur tam multi sint Epicurei, sunt aliae quoque causae, sed multitudinem haec maxime allicit, quod ita putant dici ab.', '1', '7');
INSERT INTO "Notification" ("id", "createdAt", "text", "isSeen", "userId") VALUES ('16', '2024-01-16 04:54:58', 'Oculis quidem exercitus. -- Quid ex eo perciperet corpore voluptatem.', '0', '8');
INSERT INTO "Notification" ("id", "createdAt", "text", "isSeen", "userId") VALUES ('17', '2024-12-31 13:46:03', 'Multos, sed imperitos --, quamquam autem et praeterita grate meminit et praesentibus ita potitur.', '0', '3');
INSERT INTO "Notification" ("id", "createdAt", "text", "isSeen", "userId") VALUES ('18', '2024-03-18 15:01:12', 'Sint conversa de Graecis? Nam si dicent ab illis.', '0', '10');
INSERT INTO "Notification" ("id", "createdAt", "text", "isSeen", "userId") VALUES ('19', '2024-09-15 07:28:56', 'Pro vero probatum sit, sublatum esse omne iudicium veri et falsi putat. Confirmat autem illud vel maxime, quod ipsa natura, ut ait ille, sciscat et probet, id est quo melius viveremus, eas ergo artes persequeretur, vivendi artem tantam tamque et operosam et perinde fructuosam relinqueret? Non ergo Epicurus ineruditus, sed ii indocti.', '1', '9');
INSERT INTO "Notification" ("id", "createdAt", "text", "isSeen", "userId") VALUES ('20', '2024-10-17 17:29:48', 'Tibi probarentur; si qua in iis rebus emolumenti.', '0', '2');
INSERT INTO "Notification" ("id", "createdAt", "text", "isSeen", "userId") VALUES ('21', '2024-09-26 21:45:35', 'Iudico, ut nihil homine videatur indignius. Ad maiora enim quaedam nos natura genuit et conformavit, ut mihi quidem nulli satis eruditi videntur, quibus nostra ignota sunt. An.', '1', '8');
INSERT INTO "Notification" ("id", "createdAt", "text", "isSeen", "userId") VALUES ('22', '2024-04-07 00:53:37', 'Totam rationem everti, si ita res se habeat. Nam si dicent ab illis has res esse tractatas, ne ipsos quidem Graecos est cur dubitemus dicere et sapientiam propter voluptates expetendam et dolorem.', '0', '2');
INSERT INTO "Notification" ("id", "createdAt", "text", "isSeen", "userId") VALUES ('23', '2024-12-02 03:01:49', 'Dicant foedus esse quoddam sapientium, ut ne minus amicos quam se ipsos penitus perdiderunt, sic robustus animus et excelsus omni est liber cura et.', '0', '8');
INSERT INTO "Notification" ("id", "createdAt", "text", "isSeen", "userId") VALUES ('24', '2024-03-06 05:56:19', 'Quidem, inquit, totum Epicurum paene e philosophorum choro sustulisti. Quid ei.', '0', '2');
INSERT INTO "Notification" ("id", "createdAt", "text", "isSeen", "userId") VALUES ('25', '2024-12-24 14:37:39', 'Modum eae semper voluptatibus inhaererent, eadem.', '1', '1');
INSERT INTO "Notification" ("id", "createdAt", "text", "isSeen", "userId") VALUES ('26', '2024-04-27 19:02:22', 'Istius philosophi non offendit; nam et laetamur amicorum laetitia aeque atque nostra et pariter dolemus angoribus.', '1', '8');
INSERT INTO "Notification" ("id", "createdAt", "text", "isSeen", "userId") VALUES ('27', '2024-05-23 03:03:53', 'Animi noctesque diesque exeduntur, a diis inmortalibus sine ullo metu vera sentit, non dubitat, si ita melius sit, migrare de vita. His.', '0', '1');
INSERT INTO "Notification" ("id", "createdAt", "text", "isSeen", "userId") VALUES ('28', '2025-01-09 21:57:08', 'Quam continens, quam severa sit. Non enim hanc solam sequimur, quae suavitate aliqua naturam ipsam movet et cum iucunditate quadam percipitur sensibus, sed maximam voluptatem illam habemus, quae percipitur omni dolore et molestia perfruique maximis et animi et corporis voluptatibus, videtisne quam nihil praetermittatur quod vitam adiuvet, quo facilius id, quod his libris quaeritur, qui sit.', '0', '8');
INSERT INTO "Notification" ("id", "createdAt", "text", "isSeen", "userId") VALUES ('29', '2024-07-29 21:32:37', 'Aeque doleamus animo, cum corpore dolemus, fieri tamen permagna accessio potest, si aliquod aeternum et infinitum impendere malum.', '1', '5');
INSERT INTO "Notification" ("id", "createdAt", "text", "isSeen", "userId") VALUES ('30', '2024-03-18 22:57:23', 'Quas molestias excepturi sint, obcaecati cupiditate non provident, similique sunt in culpa qui officia deserunt mollitia animi, id est vel summum bonorum vel ultimum vel extremum -- quod et acutum genus est et ab Epicuro scriptum est et ad usus civium non.', '0', '9');
INSERT INTO "Notification" ("id", "createdAt", "text", "isSeen", "userId") VALUES ('31', '2024-07-29 06:52:01', 'Etenim si delectamur, cum scribimus, quis est tam invidus, qui ab eo ortum, tam inportuno tamque crudeli; sin, ut dolore suo sanciret militaris imperii disciplinam exercitumque in gravissimo.', '0', '5');
INSERT INTO "Notification" ("id", "createdAt", "text", "isSeen", "userId") VALUES ('32', '2024-08-07 08:20:37', 'Et metu maximeque cruciantur, cum sero sentiunt frustra se aut pecuniae studuisse.', '1', '5');
INSERT INTO "Notification" ("id", "createdAt", "text", "isSeen", "userId") VALUES ('33', '2024-08-24 13:28:04', 'Locus. Nunc autem explicabo, voluptas ipsa quae qualisque sit, ut.', '1', '5');
INSERT INTO "Notification" ("id", "createdAt", "text", "isSeen", "userId") VALUES ('34', '2024-09-13 04:54:03', 'Propter molestias esse fugiendam? Eademque ratione ne temperantiam quidem propter se esse iucunda, per se esse expetendam et dolorem ipsum per se ipsas tam expetendas, quam nostras expeteremus.', '1', '5');
INSERT INTO "Notification" ("id", "createdAt", "text", "isSeen", "userId") VALUES ('35', '2024-04-21 19:28:32', 'Sequimur, quae suavitate aliqua naturam ipsam movet et cum iucunditate quadam percipitur sensibus, sed maximam voluptatem illam habemus, quae percipitur omni dolore detracto, nam quoniam, cum privamur dolore, ipsa liberatione et vacuitate omnis molestiae gaudemus, omne.', '0', '6');
INSERT INTO "Notification" ("id", "createdAt", "text", "isSeen", "userId") VALUES ('36', '2024-05-17 06:37:54', 'Eoque intellegi potest quanta voluptas sit non.', '1', '10');
INSERT INTO "Notification" ("id", "createdAt", "text", "isSeen", "userId") VALUES ('37', '2024-06-06 08:47:19', 'Quisquis enim sentit, quem ad modum, quaeso, interpretaris? Sicine eos censes aut in liberos atque in sanguinem suum tam crudelis fuisse, nihil ut de utilitatibus, nihil ut de commodis suis cogitarent? At id ne ferae quidem faciunt, ut ita ruant itaque turbent, ut earum motus et impetus quo pertineant non intellegamus, tu tam egregios viros censes.', '0', '4');
INSERT INTO "Notification" ("id", "createdAt", "text", "isSeen", "userId") VALUES ('38', '2024-10-05 22:41:03', 'Vindicet et ipsius fortunae modice ferre doceat iniurias et omnis monstret vias, quae ad amicos pertinerent, negarent esse per se ipsam optabilem, sed quia non numquam eius modi.', '1', '4');
INSERT INTO "Notification" ("id", "createdAt", "text", "isSeen", "userId") VALUES ('39', '2024-06-29 15:30:45', 'Liberamur mortis metu, non conturbamur ignoratione.', '0', '8');
INSERT INTO "Notification" ("id", "createdAt", "text", "isSeen", "userId") VALUES ('40', '2024-04-30 04:21:32', 'Labefactetur oratio mea --. Nam cum ignoratione.', '1', '10');
INSERT INTO "Notification" ("id", "createdAt", "text", "isSeen", "userId") VALUES ('41', '2024-11-26 03:34:34', 'Quas nulla praeda umquam improbe parta minuit, sed potius inflammat, ut coercendi magis quam dedocendi esse videantur. Invitat igitur vera ratio bene sanos in viam placatae, tranquillae, quietae, beatae vitae disciplinam iuvaret. An ille tempus aut.', '0', '10');
INSERT INTO "Notification" ("id", "createdAt", "text", "isSeen", "userId") VALUES ('42', '2024-07-02 13:16:54', 'Disputationi vel maxime necessarius de amicitia, quam, si voluptas summum sit bonum.', '1', '9');
INSERT INTO "Notification" ("id", "createdAt", "text", "isSeen", "userId") VALUES ('43', '2024-08-19 09:57:22', 'Depulsa est, ipsa detractio molestiae consecutionem affert voluptatis, sic in omni re doloris amotio successionem efficit voluptatis. Itaque non placuit Epicuro medium esse quiddam inter dolorem et voluptatem.', '1', '4');
INSERT INTO "Notification" ("id", "createdAt", "text", "isSeen", "userId") VALUES ('44', '2025-01-01 04:15:31', 'Quidem adduci vix possum, ut ea, quae hoc.', '1', '6');
INSERT INTO "Notification" ("id", "createdAt", "text", "isSeen", "userId") VALUES ('45', '2024-04-22 11:06:12', 'Robustus animus et excelsus omni est liber cura et angore, cum et mortem contemnit, qua qui est imbutus quietus esse numquam potest. Praeterea bona praeterita grata recordatione renovata delectant. Est autem situm in nobis ut et adversa quasi perpetua oblivione obruamus et secunda iucunde ac suaviter meminerimus. Sed.', '0', '1');
INSERT INTO "Notification" ("id", "createdAt", "text", "isSeen", "userId") VALUES ('46', '2024-09-03 07:14:41', 'Voluptatem ex infinito tempore aetatis percipi posse, quam ex hoc facillime perspici potest: Constituamus aliquem magnis, multis, perpetuis fruentem et animo et.', '0', '6');
INSERT INTO "Notification" ("id", "createdAt", "text", "isSeen", "userId") VALUES ('47', '2024-06-20 11:41:23', 'Conveniunt, qua qui affecti sunt in culpa qui officia deserunt mollitia animi, id est laborum et dolorum fuga. Et harum quidem rerum.', '1', '4');
INSERT INTO "Notification" ("id", "createdAt", "text", "isSeen", "userId") VALUES ('48', '2024-08-16 13:27:38', 'Expetendum possimus dicere? Inesse enim necesse est effici, ut.', '0', '3');
INSERT INTO "Notification" ("id", "createdAt", "text", "isSeen", "userId") VALUES ('49', '2024-11-04 07:11:44', 'Eo miserius dici aut fingi potest? Quodsi vita doloribus referta maxime fugienda est, summum profecto malum est vivere.', '1', '10');
INSERT INTO "Notification" ("id", "createdAt", "text", "isSeen", "userId") VALUES ('50', '2024-10-05 17:19:06', 'Primum in eo non arbitrantur. Erunt etiam, et ii quidem eruditi Graecis litteris, contemnentes Latinas, qui se dicant in Graecis legendis operam malle consumere. Postremo aliquos futuros suspicor, qui me ad alias litteras vocent, genus hoc scribendi, etsi sit.', '1', '4');
